export const HOME_MODES114={explore:{n:'01',title:'Explorar trenes',tag:'DESCUBRE LA FLOTA',description:'Acércate a un tren y descubre cómo está construido.',steps:['Elige NM-22, NM-79 o MP-82 en el taller.','Gira, acerca y desplaza la cámara.','Selecciona una pieza y abre su despiece.'],action:'Entrar al taller',icon:'M4 20V7l8-4 8 4v13M8 20v-7h8v7M8 8h8'},maintenance:{n:'02',title:'Misiones de taller',tag:'APRENDE HACIENDO',description:'Encuentra la falla e intervén sobre las piezas del banco.',steps:['Selecciona una de las cuatro prácticas.','Consulta el manual y elige tu herramienta.','Usa clic o arrastre y comprueba la reparación.'],action:'Elegir una misión',icon:'m14 6 4-3 3 3-3 4-4-1-8 11-3-3 10-8z'},operator:{n:'03',title:'Conducir el Metro',tag:'TU LUGAR ES LA CABINA',description:'Toma los mandos y lleva el tren de estación en estación.',steps:['Aplica tracción y controla la velocidad.','Frena y alinea el tren con el andén.','Abre las puertas y completa el aviso de cierre.'],action:'Entrar en cabina',icon:'M4 18a8 8 0 1 1 16 0M12 16l5-7M5 20h14'},automatic:{n:'04',title:'Seguir un tren',tag:'UNA CIUDAD EN MOVIMIENTO',description:'Observa el recorrido y cambia tu punto de vista.',steps:['Elige una línea y un convoy.','Usa Seguir tren para ver el recorrido con cortes.','Cambia a Andén fijo para verlo llegar.'],action:'Iniciar seguimiento',icon:'M5 4h14v14H5zM8 8h8M8 12h8M8 18l-2 3m10-3 2 3'},substations:{n:'05',title:'Explorar subestaciones',tag:'LA ENERGIA DEL METRO',description:'Entra a la subestación rectificadora y descubre sus equipos.',steps:['Explora el modelo realizado en Blender.','Abre el interior y selecciona un equipo.','Aísla sus componentes y consulta su función.'],action:'Explorar la subestación',icon:'M13 2 5 14h6l-1 8 9-13h-7z'}};
export class HomeMenu114{
 constructor(doc=document,win=window){this.doc=doc;this.win=win;this.$=id=>doc.getElementById(id);const home=this.$('game-home');if(!home||this.$('home114'))return;this.buttons=new Map([...doc.querySelectorAll('[data-game-mode]')].map(b=>[b.dataset.gameMode,b]));if(this.buttons.size!==5)return;
 const menu=this.$('game-home-menu'),title=this.$('game-home-title'),career=home.querySelector('.g105-career');const old=[...home.children];const root=doc.createElement('div');root.id='home114';root.innerHTML=`<div class="home114-top"><a class="home114-brand" href="#game-home-title" aria-label="MetroLab, portada"><span>M</span><b>METROLAB<small>CIUDAD DE MÉXICO</small></b></a><div><button id="home114-library">Información</button><button id="home114-settings">Ajustes</button></div></div><div class="home114-layout"><div class="home114-main"><div class="home114-eyebrow"><i></i> TU TURNO EN EL METRO <span>LÍNEAS 1 + 8</span></div><div id="home114-title-slot"></div><p class="home114-intro">Descubre sus piezas. Resuelve una falla.<br>Toma los mandos de tu próximo recorrido.</p><div class="home114-mode-heading"><h2>Elige tu experiencia</h2><span>5 MODOS DE JUEGO</span></div></div><aside class="home114-brief" aria-labelledby="home114-mode-title"><div class="home114-brief-top"><span>LISTO PARA COMENZAR</span><b id="home114-number">01</b></div><span class="home114-brief-tag" id="home114-tag"></span><h2 id="home114-mode-title"></h2><p id="home114-description"></p><ol id="home114-steps"></ol><button id="home114-start"><span id="home114-start-label"></span><i aria-hidden="true">→</i></button><div id="home114-career"></div></aside></div><div id="home114-menu-slot"></div><div class="home114-bottom"><div class="home114-lines"><span><i class="home114-l1">1</i> NM-22</span><span><i class="home114-l8">8</i> NM-79 · MP-82</span></div><p><kbd>1</kbd>–<kbd>5</kbd> Elegir modo <span>·</span> <kbd>Entrar</kbd> Comenzar</p><small>EXPLORA · PRACTICA · CONDUCE</small></div>`;home.append(root);this.$('home114-title-slot').append(title);title.innerHTML='METRO<span>CDMX</span>';this.$('home114-menu-slot').append(menu);if(career)this.$('home114-career').append(career);for(const node of old)node.remove();
 for(const[id,b]of this.buttons){const mode=HOME_MODES114[id];b.innerHTML=`<span class="home114-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="${mode.icon}"/></svg></span><span class="home114-card-copy"><small>MODO ${mode.n}</small><b>${mode.title}</b><span>${{explore:'Modelos, piezas y despiece',maintenance:'Herramientas y retos prácticos',operator:'Tracción, freno y puertas',automatic:'Cámaras, trenes y recorridos',substations:'Interior, equipos y energía'}[id]}</span></span><i class="home114-card-arrow" aria-hidden="true">↗</i>`;b.setAttribute('aria-describedby','home114-description');b.addEventListener('pointerenter',()=>this.preview(id));b.addEventListener('focus',()=>this.preview(id));}
 this.$('home114-start').onclick=()=>this.buttons.get(this.selected).click();this.$('home114-settings').onclick=()=>win.metroGameShell105?.openSettings();this.$('home114-library').onclick=()=>this.$('documents-open').click();win.addEventListener('keydown',e=>{if(doc.body.dataset.gameScreen!=='home'||doc.querySelector('dialog[open]')||e.ctrlKey||e.metaKey||e.altKey||e.target?.isContentEditable||['INPUT','SELECT','TEXTAREA'].includes(e.target?.tagName))return;const ids=[...this.buttons.keys()];if(/^[1-5]$/.test(e.key)){e.preventDefault();const id=ids[Number(e.key)-1];this.preview(id);this.buttons.get(id).focus();}else if(['ArrowLeft','ArrowRight'].includes(e.key)&&[...this.buttons.values()].includes(e.target)){e.preventDefault();const index=(ids.indexOf(this.selected)+(e.key==='ArrowRight'?1:ids.length-1))%ids.length;this.preview(ids[index]);this.buttons.get(ids[index]).focus();}});this.preview('explore');
 }
 preview(id){const mode=HOME_MODES114[id];if(!mode)return;this.selected=id;this.$('home114').dataset.mode=id;for(const[key,b]of this.buttons)b.setAttribute('data-preview114',String(key===id));this.$('home114-number').textContent=mode.n;this.$('home114-tag').textContent=mode.tag;this.$('home114-mode-title').textContent=mode.title;this.$('home114-description').textContent=mode.description;this.$('home114-steps').innerHTML=mode.steps.map(s=>'<li>'+s+'</li>').join('');this.$('home114-start-label').textContent=mode.action;}
}
if(typeof document!=='undefined'){const mount=()=>{if(window.metroGame&&window.metroGameShell105&&!document.getElementById('home114'))window.metroHome114=new HomeMenu114();};mount();if(!document.getElementById('home114')){const observer=new MutationObserver(()=>{mount();if(document.getElementById('home114'))observer.disconnect();});observer.observe(document.body,{childList:true,subtree:true});}}
